<header class="at-head"><span>Administración</span><h1>Papelera</h1><p>Los elementos pueden restaurarse durante 60 días antes de su purga.</p></header>
<?php if($trashError):?><p class="at-error"><?=e($trashError)?></p><?php endif;?>
<section class="at-stats"><article><strong><?=$trashData['summary']['users']?></strong><span>Usuarios</span></article><article><strong><?=$trashData['summary']['projects']?></strong><span>Proyectos</span></article><article><strong><?=$trashData['summary']['expired']?></strong><span>Listos para purgar</span></article></section>
<section class="at-remove"><h2>Retirar acceso de un usuario</h2><form id="atUserForm"><input type="hidden" name="_csrf" value="<?=e($trashCsrf)?>"><select name="id" required><option value="">Selecciona una cuenta</option><?php foreach($trashData['candidates']??[] as $u):?><option value="<?=$u['id']?>"><?=e($u['full_name'].' · '.$u['email'])?></option><?php endforeach;?></select><input name="reason" minlength="5" required placeholder="Motivo de eliminación"><button>Enviar a Papelera</button></form></section>
<nav class="at-tabs"><a class="<?=$trashData['active_type']==='users'?'active':''?>" href="<?=e(route('admin-trash').'&trash_type=users')?>">Usuarios</a><a class="<?=$trashData['active_type']==='projects'?'active':''?>" href="<?=e(route('admin-trash').'&trash_type=projects')?>">Proyectos</a><button id="atPurge" <?=$trashData['summary']['expired']?'':'disabled'?>>Purgar vencidos</button></nav>
<?php $key=$trashData['active_type'];$label=$key==='users'?'Usuarios eliminados':'Proyectos eliminados';?>
<section class="at-list active" data-panel="<?=$key?>"><?php if(!$trashData[$key]):?><div class="at-empty">No hay <?=e(mb_strtolower($label))?>.</div><?php else:foreach($trashData[$key] as $item):?><article><div><strong><?=e($item['full_name']??$item['title'])?></strong><small><?=e($item['email']??$item['code'])?></small></div><div><span>Eliminado por <?=e($item['deleted_by_name']?:'Sistema')?></span><small><?=e($item['deletion_reason']?:'Sin motivo registrado')?></small></div><strong><?=$item['days_left']?> días restantes</strong><button data-restore data-entity="<?=substr($key,0,-1)?>" data-id="<?=$item['id']?>">Restaurar</button></article><?php endforeach;endif;?></section>
<div id="atConfig" data-user="<?=e($trashEndpoints['user'])?>" data-restore="<?=e($trashEndpoints['restore'])?>" data-purge="<?=e($trashEndpoints['purge'])?>" data-csrf="<?=e($trashCsrf)?>"></div>
